1	// Shared between the browser and the local dev-server proxy (server/aiProxy.ts).
2	// Everything the model may output is checked here, so the game never shows unchecked text.
3	
4	export type FortuneLevel = '上上' | '上' | '中' | '下';
5	
6	export interface AiFortune {
7	  level: FortuneLevel;
8	  poem: [string, string, string, string];
9	  read: string;
10	}
11	
12	export interface AiLetter {
13	  /** A small, gentle physical object the worry turns into. */
14	  item: string;
15	  /** Recipient NPC id (whitelisted, never the station master). */
16	  to: string;
17	  /** What 老周 says when handing the item over. */
18	  offer: [string, string];
19	  /** What the recipient says on delivery. */
20	  thanks: [string, string];
21	  /** The reply letter shown after delivery. */
22	  reply: string;
23	}
24	
25	export type AiTask = 'fortune' | 'letter';
26	
27	export interface AiRequest {
28	  task: AiTask;
29	  text: string;
30	  /** Residents who received the player's recent letters; the model should pick someone else. */
31	  avoid?: string[];
32	}
33	
34	export type AiSource = 'ai' | 'fallback' | 'safety';
35	
36	export interface AiResponse<T> {
37	  source: AiSource;
38	  data: T | null;
39	  /** Why we fell back (no key, timeout, invalid output, refusal ...). */
40	  reason?: string;
41	  ms?: number;
42	}
43	
44	export const MAX_INPUT = 60;
45	
46	/** Recipients the model may pick. 老周 is the post office, so he is not a recipient. */
47	export const RECIPIENTS: { id: string; name: string; title: string; voice: string; good: string }[] = [
48	  { id: 'chen', name: '小陈', title: '便利店夜班', voice: '年轻，话少，观察细，偶尔冷幽默', good: '深夜睡不着、一个人的晚上、说不出口的小事' },
49	  { id: 'gan', name: '阿甘', title: '变电所值班', voice: '憨厚，嘴硬心软，爱用电和灯打比方', good: '压力大、快撑不住、电量耗尽的感觉' },
50	  { id: 'wu', name: '吴阿姨', title: '自助洗衣店', voice: '温和的长辈，不说教，常说"放我这儿吧"', good: '一时想不清、需要先放一放的事、犹豫要不要放弃' },
51	  { id: 'mian', name: '老板娘', title: '拉面摊', voice: '爽利，记得每个人的口味，用吃饭打比方', good: '钱、房租、没好好吃饭、生活琐碎' },
52	  { id: 'lin', name: '林工', title: '加班大厦', voice: '同样被工作困住的人，自嘲，感同身受', good: '被退回的工作、开不完的会、职场里的委屈' },
53	  { id: 'man', name: '小满', title: '夜间植物员', voice: '轻声细语，用植物生长打比方，很慢', good: '进步太慢、焦虑、和别人比较、等结果' },
54	  { id: 'tang', name: '老唐', title: '信号塔', voice: '孤独的老人，看得远，话短，像电报', good: '想念远方的人、异地、联系不上、没人回消息' },
