199	    const siteHints: Record<string, string> = {
200	      temple: '烧香 · 拜佛 · 抽签 · 敲木鱼',
201	      church: '听歌 · 点蜡烛 · 祈祷',
202	      dao: '打坐修仙 · 炼丹',
203	    };
204	    for (const s of this.world.sites) {
205	      this.siteTags.push({
206	        tag: new Tag(this.ui.anchors, s.name, siteHints[s.id] ?? '', 'site'),
207	        dir: s.frame.center.clone(),
