276	  private makeBody(look: Look, dir: THREE.Vector3, fwd: THREE.Vector3, name: string, sub: string, cls: string): Body {
277	    const avatar = new Avatar(look);
278	    this.scene.add(avatar.root);
279	    const shadow = new THREE.Mesh(shadowGeo, shadowMat);
280	    shadow.renderOrder = 1;
281	    this.scene.add(shadow);
282	    const tag = new Tag(this.ui.anchors, name, sub, cls);
283	    return { avatar, dir: dir.clone(), fwd: fwd.clone(), h: 0, ground: 0, speed: 0, tag, shadow, wave: 0, pose: 'stand', gesture: 'none', gt: 0, scale: 1 };
284	  }
