426	  private emote(i: number) {
427	    const e = EMOJIS[i];
428	    if (!e) return;
429	    this.me.tag.bubble(e);
430	    if (!this.act) this.me.wave = 1.2;
431	    this.audio.play('emoji');
432	    this.presence.emoji(e);
433	    for (const r of this.residents) {
434	      if (r.avatar.root.visible && surfDist(r.dir, this.me.dir) < 6 && Math.random() < 0.8) {
435	        setTimeout(() => {
436	          r.tag.bubble(EMOJIS[[0, 1, 6, 5][Math.floor(Math.random() * 4)]]);
437	          r.wave = 1.2;
438	        }, 600 + Math.random() * 900);
439	      }
440	    }
441	  }
