452	  private frame() {
453	    const dt = Math.min(this.clock.getDelta(), 0.05);
454	    this.time += dt;
455	    this.sky.update(dt, this.time);
456	    this.tram.update(dt);
457	    for (const b of this.world.blinkers) {
458	      const period = b.userData.blink as number;
459	      b.visible = Math.sin((this.time * Math.PI * 2) / period) > -0.3;
460	    }
461	    for (const e of this.world.emitters) e.update(dt, this.time);
462	    this.qi.update(dt, this.time);
463	    this.effects.update(dt);
464	    this.world.flames.forEach((f, i) => {
465	      if (f.visible) f.scale.set(1, 1 + Math.sin(this.time * 13 + i * 1.7) * 0.18, 1);
466	    });
467	
468	    if (this.mode === 'title') this.titleCamera();
469	    else {
470	      if (this.mode === 'play') {
471	        this.updatePlayer(dt);
472	        this.updateScene();
473	        this.updatePill();
474	      }
475	      this.updateCamera(dt);
476	      if (this.mode === 'play') this.updateInteract();
477	    }
478	
479	    this.updateNpcs(dt);
480	    this.updateResidents(dt);
481	    this.updatePeers(dt);
482	    this.poseBody(this.me, dt, !this.onGround && !this.act, this.inWater);
483	    this.updateLight();
484	    this.renderer.render(this.scene, this.camera);
485	    this.placeTags();
486	
487	    this.sendClock -= dt;
488	    if (this.mode !== 'title' && this.sendClock <= 0) {
489	      this.sendClock = 0.1;
490	      const card = this.store.wearingCard;
491	      this.presence.send({
492	        name: card?.name ?? '过客',
493	        job: card?.jobName ?? '',
494	        look: this.me.avatar.look,
495	        d: this.me.dir.toArray() as [number, number, number],
496	        f: this.me.fwd.toArray() as [number, number, number],
497	        h: this.me.h,
498	        sp: this.me.speed,
499	        anim: !this.onGround && !this.act ? 'air' : this.me.speed > 0.2 ? 'walk' : 'idle',
500	        pose: this.me.pose,
501	        gesture: this.me.gesture,
502	        scale: this.me.scale,
503	        aura: this.auraColor(),
504	      });
505	      this.presence.prune();
