564	  private updatePlayer(dt: number) {
565	    const me = this.me;
566	    const up = me.dir;
567	    const ax = this.input.axis();
568	    const emote = this.input.consumeEmote();
569	    if (emote !== null) this.emote(emote);
570	
571	    if (this.act) {
572	      this.updateActivity(dt, ax.mag);
573	      me.speed = 0;
574	      return;
575	    }
576	    me.pose = 'stand';
577	    me.gesture = 'none';
578	    const jump = this.input.consumeJump();
579	
580	    const camF = tmpV2.copy(this.cam.dir).applyAxisAngle(up, this.cam.yaw);
581	    projectTangent(camF, up).normalize();
582	    const camR = new THREE.Vector3().crossVectors(camF, up).normalize();
583	    const want = new THREE.Vector3().addScaledVector(camF, ax.y).addScaledVector(camR, ax.x);
584	    const swift = this.pill?.kind === 'swift' ? 1.6 : 1;
585	    const targetSpeed = ax.mag * (ax.run ? RUN : WALK) * (this.inWater ? 0.6 : 1) * swift;
586	    if (want.lengthSq() > 1e-4) {
587	      want.normalize();
588	      this.moveDir.copy(want);
589	      if (me.fwd.dot(want) < -0.9) me.fwd.addScaledVector(camR, 0.2);
590	      me.fwd.lerp(want, 1 - Math.exp(-dt * 12)).normalize();
591	    }
592	    me.speed += (targetSpeed - me.speed) * (1 - Math.exp(-dt * (targetSpeed > me.speed ? 10 : 7)));
593	    if (me.speed > 0.01 && this.moveDir.lengthSq() > 0.5) {
594	      surfaceStep(up, this.moveDir, me.speed * dt, tmpQ);
595	      for (const v of [me.dir, me.fwd, this.cam.dir, this.moveDir]) v.applyQuaternion(tmpQ);
596	    }
597	
598	    const ground = resolveCollisions(this.colliders, me.dir, me.h);
599	    for (const v of [me.fwd, this.cam.dir, this.moveDir]) projectTangent(v, me.dir).normalize();
600	
601	    if (jump && this.onGround) {
602	      this.vh = JUMP * (this.pill?.kind === 'light' ? 1.55 : 1);
603	      this.onGround = false;
604	      this.audio.play('jump');
605	    }
606	    if (ground > me.h && ground - me.h < 0.4 && this.onGround) me.h = ground;
607	    this.vh -= GRAVITY * dt;
608	    me.h += this.vh * dt;
609	    if (me.h <= ground) {
610	      if (!this.onGround && this.vh < -4) this.audio.play('land');
611	      me.h = ground;
612	      this.vh = 0;
613	      this.onGround = true;
614	    } else if (me.h - ground > 0.05) {
615	      this.onGround = false;
616	    }
617	    me.ground = ground;
618	    const pd = Math.acos(THREE.MathUtils.clamp(me.dir.dot(this.world.pondDir), -1, 1)) * (180 / Math.PI);
619	    this.inWater = pd < this.world.pondRadius - 0.6 && ground === 0;
620	  }
