922	    const cin = this.input.consumeCamera();
923	    if (this.mode === 'play') {
924	      this.cam.yaw -= cin.dx * 0.0065;
925	      this.cam.pitch = THREE.MathUtils.clamp(this.cam.pitch + cin.dy * 0.004, 0.05, 1.0);
926	      this.cam.dist = THREE.MathUtils.clamp(this.cam.dist + cin.zoom * 0.7, 3.6, 12);
927	    }
928	    projectTangent(this.cam.dir, me.dir).normalize();
929	    if (me.speed > 0.6 && !this.input.dragging && !this.act) {
930	      if (Math.abs(this.cam.yaw) > 1e-4) {
931	        this.cam.dir.applyAxisAngle(me.dir, this.cam.yaw);
932	        this.cam.yaw = 0;
933	      }
934	      const align = (1 + this.cam.dir.dot(me.fwd)) / 2;
935	      this.cam.dir.lerp(me.fwd, (1 - Math.exp(-dt * 1.8)) * align * align).normalize();
