939	    const focus = this.cam.focus.lerp(pos.clone().addScaledVector(me.dir, 1.2), this.mode === 'fly' ? 1 : 1 - Math.exp(-dt * 12));
940	    const desired = focus
941	      .clone()
942	      .addScaledVector(camF, -this.cam.dist * Math.cos(this.cam.pitch))
943	      .addScaledVector(up, this.cam.dist * Math.sin(this.cam.pitch) + 0.4);
944	    const lookAt = focus.clone().addScaledVector(camF, 1.6);
945	
946	    if (this.mode === 'fly') {
947	      this.flyT += dt / 2.6;
948	      const t = Math.min(1, this.flyT);
949	      const e = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
950	      const m = new THREE.Matrix4().lookAt(desired, lookAt, up);
951	      const qTo = new THREE.Quaternion().setFromRotationMatrix(m);
952	      const fromDir = this.flyFrom.pos.clone().normalize();
953	      const toDir = desired.clone().normalize();
954	      const qd = new THREE.Quaternion().setFromUnitVectors(fromDir, toDir);
955	      const dirNow = fromDir.applyQuaternion(new THREE.Quaternion().slerp(qd, e));
956	      const r = THREE.MathUtils.lerp(this.flyFrom.pos.length(), desired.length(), e);
957	      this.camera.position.copy(dirNow.multiplyScalar(r));
958	      this.camera.quaternion.copy(this.flyFrom.quat).slerp(qTo, e);
959	      if (t >= 1) {
960	        this.mode = 'play';
961	        this.onPlayStart();
962	      }
963	      return;
964	    }
965	    let target = desired;
966	    let blocked = false;
967	    const probe = new THREE.Vector3();
968	    for (let pass = 0; pass < 2 && !blocked; pass++) {
969	      for (let i = 2; i <= 14; i++) {
970	        probe.copy(focus).lerp(target, i / 14);
971	        const hit = pointBlocked(this.colliders, probe, 0.25, 0.7);
972	        if (!hit) continue;
973	        if (hit.bottom !== undefined && pass === 0) {
974	          const local = probe.clone().normalize().sub(hit.c).multiplyScalar(R).lengthSq() / (2 * R);
975	          const over = target.length() - R - (hit.bottom + local - 0.45);
976	          target = target.clone().addScaledVector(up, -Math.max(0, over));
977	          break;
978	        }
979	        target = focus.clone().lerp(target, Math.max(0.1, (i - 1.5) / 14));
980	        blocked = true;
981	        break;
982	      }
983	    }
984	    if (blocked && pointBlocked(this.colliders, this.camera.position, 0.1, 0.7)) this.camera.position.copy(target);
985	    else this.camera.position.lerp(target, 1 - Math.exp(-dt * (blocked ? 18 : 7)));
986	    this.camera.up.copy(up);
987	    this.camera.lookAt(lookAt);
