1	// Local dev-server middleware: POST /api/ai
2	// The API key stays on this machine (read from .env.local) and never reaches the browser bundle.
3	// Every call is appended to logs/ai-trace.log so runs can be replayed and compared.
4	
5	import { appendFileSync, mkdirSync } from 'node:fs';
6	import type { IncomingMessage, ServerResponse } from 'node:http';
7	import Anthropic from '@anthropic-ai/sdk';
8	import { zodOutputFormat } from '@anthropic-ai/sdk/helpers/zod';
9	import { z } from 'zod';
10	import type { Plugin } from 'vite';
11	import {
12	  MAX_INPUT,
13	  RECIPIENTS,
14	  fortuneProblems,
15	  isCrisis,
16	  letterProblems,
17	  type AiRequest,
18	  type AiResponse,
19	} from '../src/ai/shared';
20	
21	const CLAUDE_MODEL = 'claude-opus-5-5';
22	const ZHIPU_URL = 'https://open.bigmodel.cn/api/paas/v4/chat/completions';
23	
24	export interface AiEnv {
25	  /** 'zhipu' | 'anthropic'. Defaults to whichever key is present (Zhipu first). */
26	  AI_PROVIDER?: string;
27	  ANTHROPIC_API_KEY?: string;
28	  ZHIPU_API_KEY?: string;
29	  ZHIPU_MODEL?: string;
30	}
31	
32	/** What a provider returns before the shared validation step. */
33	interface RawResult {
34	  output: unknown;
35	  refused: boolean;
36	  usage: { input: number; output: number };
37	  model: string;
38	}
39	
40	type Provider = (task: AiRequest['task'], system: string, user: string) => Promise<RawResult>;
41	
42	const WORLD = `你在为一个叫「余晖站」的网页小游戏写台词。
43	余晖站是一颗很小的星球，给下了班的打工人放松用：没有分数、没有失败、没有排行榜。
44	语气：安静、温和、带一点冷幽默，像深夜便利店里的对话。
45	硬规则：
46	- 不说教，不给建议清单，不当心理咨询师，不用"加油""你要相信自己"这类鸡汤。
47	- 不要原样复述玩家写的话，把它化成具体的小物件、小场景或比喻。
48	- 不出现真实人名、公司名、品牌名。
49	- 全部用简体中文。`;
50	
51	const FORTUNE_PROMPT = `${WORLD}
52	
53	任务：玩家在余晖寺摇签前，心里默念了一件想问的事（见下）。为这件事写一支专属的签。
54	- level 只能是 上上 / 上 / 中 / 下。偏向温和，"下"签也要落在"早点休息""先放一放"这类善意上。
55	- poem 恰好 4 行，每行恰好 7 个汉字（数一数），不带任何标点；意象来自余晖站：站台、班车、便利店、晚钟、薄荷、信号塔、洗衣房、月亮。
56	- read 是解签，一到两句白话，30 字以内，具体、轻松，回应玩家问的事。`;
57	
58	const LETTER_PROMPT = `${WORLD}
59	
60	任务：玩家把一句烦心事投进了站长老周的「心事邮差」信箱（见下）。把它变成一次跑腿：
61	- item：这件烦心事变成的一件具体的小物件，16 字以内，例如"一支没电的荧光笔""一把晾不干的伞"。物件和烦心事只能是比喻关系，不能出现烦心事里的词（烦心事是"房租涨了"，就不能写"房租单"）。
