211	  const want = env.AI_PROVIDER?.trim().toLowerCase();
212	  if ((want === 'zhipu' || !want) && env.ZHIPU_API_KEY) {
213	    const models = (env.ZHIPU_MODEL?.trim() || 'glm-4.5-flash,glm-4-flash-250414').split(',').map((m) => m.trim()).filter(Boolean);
214	    return { name: `zhipu/${models.join('→')}`, call: zhipuChain(env.ZHIPU_API_KEY, models) };
