225	  const t0 = Date.now();
226	  const fortune = req.task === 'fortune';
227	  const system = fortune ? FORTUNE_PROMPT : LETTER_PROMPT;
228	  const avoid = req.avoid ?? [];
229	  let user = `玩家写的是：「${req.text}」`;
230	  if (!fortune && avoid.length) {
231	    user += `\n最近收过这位玩家信的居民（这次请换别人）：${avoid.map((id) => RECIPIENTS.find((r) => r.id === id)!.name).join('、')}`;
232	  }
