234	    const raw = await provider.call(req.task, system, user);
235	    const ms = Date.now() - t0;
236	    const base = { provider: provider.name, model: raw.model, task: req.task, text: req.text, avoid, attempt, ms, usage: raw.usage };
237	    if (raw.refused) {
