242	    trace({ ...base, result: problems.length ? 'invalid' : 'ok', problems, output: raw.output });
243	    if (!problems.length) return { source: 'ai', data: raw.output, ms };
244	    // Tell the model exactly what failed, then let it try again.
245	    user += `\n\n（第 ${attempt} 版不合格：${problems.join('；')}。请按要求重写完整的 JSON。）`;
