250	export function aiProxy(env: AiEnv): Plugin {
251	  const provider = pickProvider(env);
252	  return {
253	    name: 'yuhui-ai-proxy',
254	    configureServer(server) {
255	      server.config.logger.info(`  ➜  AI provider: ${provider?.name ?? 'none (handwritten fallback only)'}`);
256	      server.middlewares.use('/api/ai', async (req: IncomingMessage, res: ServerResponse) => {
257	        const send = (body: AiResponse<unknown>, status = 200) => {
258	          res.statusCode = status;
259	          res.setHeader('content-type', 'application/json; charset=utf-8');
260	          res.end(JSON.stringify(body));
261	        };
262	        if (req.method !== 'POST') return send({ source: 'fallback', data: null, reason: 'method' }, 405);
263	        const body = await readBody(req);
264	        if (!body) return send({ source: 'fallback', data: null, reason: 'bad-request' }, 400);
265	        if (isCrisis(body.text)) return send({ source: 'safety', data: null, reason: 'crisis' });
266	        if (!provider) return send({ source: 'fallback', data: null, reason: 'no-key' });
267	        try {
268	          send(await run(provider, body));
269	        } catch (e) {
270	          const reason =
271	            e instanceof Anthropic.RateLimitError
272	              ? 'rate-limit'
273	              : e instanceof Anthropic.APIConnectionTimeoutError
274	                ? 'timeout'
275	                : e instanceof Anthropic.APIConnectionError
276	                  ? 'network'
277	                  : e instanceof Anthropic.APIError
278	                    ? `api-${e.status}`
279	                    : e instanceof ProviderError
280	                      ? e.message.split(':')[0]
281	                      : 'error';
282	          trace({ task: body.task, text: body.text, result: reason, error: String(e) });
283	          send({ source: 'fallback', data: null, reason });
284	        }
285	      });
286	    },
287	  };
288	}
