async function readBody(req: IncomingMessage): Promise<AiRequest | null> {
  let raw = '';
  for await (const chunk of req) {
    raw += chunk;
    if (raw.length > 4000) return null;
  }
  try {
    const b = JSON.parse(raw) as AiRequest;
    if ((b.task !== 'fortune' && b.task !== 'letter') || typeof b.text !== 'string') return null;
    const avoid = Array.isArray(b.avoid) ? b.avoid.filter((id) => RECIPIENTS.some((r) => r.id === id)).slice(0, 3) : [];
    let memory: Record<string, string[]> = {};
    if (b.memory && typeof b.memory === 'object') {
      for (const [id, items] of Object.entries(b.memory)) {
        if (!RECIPIENTS.some((r) => r.id === id)) continue;
        const valid: string[] = [];
        for (const item of Array.isArray(items) ? items : []) {
          if (typeof item === 'string' && item.length <= 16) {
            valid.push(item);
          }
        }
        if (valid.length > 0) {
          memory[id] = valid.slice(0, 3);
        }
      }
    }
    return { task: b.task, text: [...b.text.trim()].slice(0, MAX_INPUT).join(''), avoid, memory };
  } catch {
    return null;
  }
}

